        if account_id != r#ref.account_id {
            return Err(MailError::NotFound);
        }
        let built = build_conversation(&conn, &account_id, &r#ref.conversation_id)?;
        let recovered = if let Some(built) = built {
            built
        } else {
            let recovered: Option<(String, String)> = conn
                .query_row(
                    "SELECT snapshot_json, snapshot_saved_at FROM gmail_operation_snapshots
                     WHERE account_id = ?1 AND conversation_id = ?2
                     UNION ALL
                     SELECT snapshot_json, COALESCE(json_extract(snapshot_json, '$.retainedSnapshotAt'), '') FROM gmail_reminders
                     WHERE account_id = ?1 AND conversation_id = ?2
                     LIMIT 1",
                    params![account_id, r#ref.conversation_id],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
                .optional()
                .map_err(storage_err())?;
            let (json, saved_at) = recovered.ok_or(MailError::NotFound)?;
            let mut snapshot: Conversation = serde_json::from_str(&json).map_err(storage_err())?;
            snapshot.retained_snapshot_at = Some(saved_at);
            let (is_in_inbox, is_read, pending_operation_id) =
                effective_conversation_state(&conn, &account_id, &r#ref.conversation_id)?;
            snapshot.is_in_inbox = is_in_inbox;
            snapshot.is_read = is_read;
            snapshot.stars = Some(star_state(&conn, &account_id, &r#ref.conversation_id)?);
            snapshot.pending_operation_id = pending_operation_id;
            return Ok(snapshot);
        };
        let (is_in_inbox, is_read, pending_operation_id) =
            effective_conversation_state(&conn, &account_id, &r#ref.conversation_id)?;
        Ok(Conversation {
            stars: Some(star_state(&conn, &account_id, &r#ref.conversation_id)?),
            conversation_ref: recovered.conversation_ref,
            subject: recovered.subject,
            messages: recovered.messages,
            is_in_inbox,
            is_read,
            context_complete: recovered.context_complete,
            unsupported_reason: recovered.unsupported_reason,
            retained_snapshot_at: None,
            reply_context: recovered.reply_context,
            pending_operation_id,
        })
    }

    /// Saves only reply metadata when the cached account, generation, and
    /// latest source message still match the read that fetched it.
    pub(crate) fn save_reply_context(
        &self,
        r#ref: &ConversationRef,
        source_message_id: &str,
        reply_context: &ReplyContext,
        expected_generation: u64,
    ) -> Result<bool, MailError> {
        self.persistence_gate()?;
        if reply_context.source_message_id != source_message_id {
            return Ok(false);
        }
        let mut conn = self.lock_conn()?;
        let tx = conn.transaction().map_err(storage_err())?;
        if meta_get(&tx, "account_id")?.as_deref() != Some(r#ref.account_id.as_str())
            || !generation_matches(&tx, expected_generation)?
        {
            return Ok(false);
        }
        let cache_state: Option<(i64, String)> = tx
            .query_row(
                "SELECT c.context_complete, m.message_id FROM gmail_conversations c
                 JOIN gmail_messages m
                   ON m.account_id = c.account_id AND m.conversation_id = c.conversation_id
                 WHERE c.account_id = ?1 AND c.conversation_id = ?2
                 ORDER BY m.sent_at DESC, m.message_id DESC LIMIT 1",
                params![r#ref.account_id, r#ref.conversation_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()
            .map_err(storage_err())?;
        if !cache_state
            .is_some_and(|(complete, latest_id)| complete == 1 && latest_id == source_message_id)
        {
            return Ok(false);
        }
        let reply_context_json = serde_json::to_string(reply_context).map_err(storage_err())?;
        let updated = tx
            .execute(
                "UPDATE gmail_conversations SET reply_context_json = ?1
                 WHERE account_id = ?2 AND conversation_id = ?3
                   AND context_complete = 1 AND reply_context_json IS NULL",
                params![reply_context_json, r#ref.account_id, r#ref.conversation_id],
            )
            .map_err(storage_err())?;
        if updated != 1 {
            return Ok(false);
        }
        tx.commit().map_err(storage_err())?;
        Ok(true)
    }
}
    Ok(())
}

pub(super) fn has_action_context(
    conn: &Connection,
    account: &str,
    id: &str,
) -> Result<bool, MailError> {
    conn.query_row(
        // Eviction removes live bodies, not operation-pinned facts/snapshots.
        // accept_operation_tx can capture fresh preimages from those same facts
        // and reuse the recovery snapshot without reading or widening targets.
        "SELECT EXISTS(SELECT 1 FROM gmail_message_facts WHERE account_id=?1 AND conversation_id=?2) AND (EXISTS(SELECT 1 FROM gmail_conversations WHERE account_id=?1 AND conversation_id=?2) OR EXISTS(SELECT 1 FROM gmail_operation_snapshots WHERE account_id=?1 AND conversation_id=?2))",
        params![account, id], |r| r.get(0)).map_err(storage_err())
}

pub(super) fn admit_search_rows(
    tx: &Connection,
    threads: &[GmailThread],
    account: &str,
) -> Result<(), MailError> {
    let seq: i64 = tx
        .query_row(
            "SELECT COALESCE(MAX(seq),0)+1 FROM gmail_search_cache",
            [],
            |r| r.get(0),
        )
        .map_err(storage_err())?;
    for thread in threads {
        if thread.conversation.conversation_ref.account_id != account {
            return Err(MailError::NotFound);
        }
        let id = &thread.conversation.conversation_ref.conversation_id;
        let ordinary: bool = tx.query_row("SELECT EXISTS(SELECT 1 FROM gmail_conversations c WHERE account_id = ?1 AND conversation_id = ?2 AND NOT EXISTS(SELECT 1 FROM gmail_search_cache s WHERE s.account_id = c.account_id AND s.conversation_id = c.conversation_id))", params![account,id], |r| r.get(0)).map_err(storage_err())?;
        // Search may admit archived threads that discovery/history omit.
        tx.execute("INSERT OR IGNORE INTO gmail_conversations (account_id, conversation_id, subject, context_complete) VALUES (?1,?2,'',0)", params![account,id]).map_err(storage_err())?;
        upsert_thread(tx, account, thread)?;
        if !ordinary {
            tx.execute(
                "INSERT OR REPLACE INTO gmail_search_cache VALUES (?1,?2,?3)",
                params![account, id, seq],
            )
            .map_err(storage_err())?;
        }
    }
    Ok(())
}

/// Defer action eviction until *all* selected members have immutable targets
/// and recovery snapshots, including already-cached members near the LRU tail.
pub(super) fn evict_search(tx: &Connection, account: &str) -> Result<(), MailError> {
    let ids = {
        let mut stmt = tx.prepare("SELECT conversation_id FROM gmail_search_cache s WHERE account_id = ?1 AND NOT EXISTS (SELECT 1 FROM gmail_reminders r WHERE r.account_id=s.account_id AND r.conversation_id=s.conversation_id AND json_extract(r.data,'$.phase')='pending') ORDER BY seq DESC, conversation_id LIMIT -1 OFFSET 100").map_err(storage_err())?;
        let ids = stmt
            .query_map([account], |r| r.get::<_, String>(0))
            .map_err(storage_err())?
            .collect::<Result<Vec<_>, _>>()
            .map_err(storage_err())?;
        ids
    };
    for id in ids {
        // Same preservation rule as discovery eviction: only unpinned facts go.
        tx.execute(
            "DELETE FROM gmail_messages WHERE account_id=?1 AND conversation_id=?2",
            params![account, id],
        )
        .map_err(storage_err())?;
        tx.execute(
            "DELETE FROM gmail_inbox_membership WHERE account_id=?1 AND conversation_id=?2",
            params![account, id],
        )
        .map_err(storage_err())?;
        tx.execute("DELETE FROM gmail_message_facts WHERE account_id=?1 AND conversation_id=?2 AND NOT EXISTS (SELECT 1 FROM gmail_operation_targets t WHERE t.account_id=gmail_message_facts.account_id AND t.message_id=gmail_message_facts.message_id)", params![account,id]).map_err(storage_err())?;
        tx.execute(
            "DELETE FROM gmail_conversations WHERE account_id=?1 AND conversation_id=?2",
            params![account, id],
        )
        .map_err(storage_err())?;
        tx.execute(
            "DELETE FROM gmail_search_cache WHERE account_id=?1 AND conversation_id=?2",
            params![account, id],
        )
        .map_err(storage_err())?;
    }

    Ok(())
}

